mapper.update:
UPDATE field_libraries
SET name = #{name},
    description = #{description,jdbcType=VARCHAR},
    updated_at = #{updatedAt}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND owner_id = #{ownerId}

mapper.select:
SELECT 
FROM field_libraries l
WHERE l.id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND l.owner_id = #{ownerId}

SELECT 
FROM field_libraries l
WHERE l.owner_id = #{ownerId}

    AND LOWER(l.name) LIKE #{keywordPattern}

ORDER BY l.updated_at DESC, l.name ASC

mapper.delete:
