mapper.select:
SELECT COUNT(*)
FROM field_libraries
WHERE owner_id = #{ownerId}
  AND LOWER(name) = LOWER(#{name})

    AND id <> #{excludeId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
